'use strict';

const os = require('os');
const path = require('path');
const Base = require('diskstore');
const glob = require('mz-modules/glob');
const utility = require('utility');

const NOTE_PREFIX = '//';
const DEFAULT_OPTIONS = {
  cacheDir: path.join(os.homedir(), 'conf/antvip-node-client-cache'),
};

class DiskStore extends Base {
  constructor(options) {
    super(Object.assign({}, DEFAULT_OPTIONS, options, { initMethod: null }));
  }

  async loadVipDomains() {
    const files = await glob('*.json', {
      cwd: path.join(this.cacheDir, 'domains'),
      silent: true,
    });
    const list = [];
    for (const file of files) {
      const data = await this.get(`domains/${file}`);
      if (data) {
        let content = data.toString();
        if (content.startsWith(NOTE_PREFIX)) {
          content = content.slice(content.indexOf('\n') + 1);
        }
        list.push(JSON.parse(content.trim()));
      }
    }
    return list;
  }

  async deleteVipDomain(domainName) {
    try {
      this.delete(`domains/${domainName}.json`);
    } catch (_) { /* ignore */ }
  }

  async storeVipDomain(vipDomain) {
    await this.set(`domains/${vipDomain.name}.json`, `${NOTE_PREFIX} ${utility.YYYYMMDDHHmmssSSS()}\n${JSON.stringify(vipDomain)}`);
  }

  async storeVipDomains(vipDomains) {
    await vipDomains.map(dom => this.storeVipDomain(dom));
  }
}

module.exports = DiskStore;
